Q: How to access bash variable in python script via hql file(bash-hql-python) A: <pre><code>/* ============================================================
   SCRIPT TASK: &quot;Discover File + Extract FileDate&quot;
   ============================================================
   Branches on IsFileNameDateConstrained (from ETLJobMgmt, via
   Etl_JobInfo_Lookup) so the same script can support jobs whose
   filenames always carry a date (this job) as well as jobs that
   don't, without rewriting the script per job.

   - Filename prefixes are package parameters, not hardcoded.
   - Archiving is handled by two File System Tasks in the control
     flow, not in this script. See walkthrough for setup.

   SSIS variables/parameters used:

   READ:
     $Package::SourceFolderPath        (String)  e.g. C:\path\folder\subfolder\
     $Package::CleanedFilePrefix       (String)  e.g. test_cleaned_
     $Package::OrigFilePrefix          (String)  e.g. test_orig_
     $Package::FileDateOverride        (String)  &quot;20260620&quot; or &quot;&quot; - backfill only
     $Package::IsManualBackfill        (Boolean)
     User::IsFileNameDateConstrained   (Boolean) -- from Etl_JobInfo_Lookup
     User::NextExpectedDateValue       (DateTime)-- from Etl_JobInfo_Lookup

   WRITE:
     User::FileDate              (DateTime)
     User::CleanedFileName       (String)
     User::CleanedFileFullPath   (String)
     User::OrigFileName          (String)   -- needed by the File System Task for archiving
     User::OrigFileFullPath      (String)
   ============================================================ */

using System;
using System.IO;
using Microsoft.SqlServer.Dts.Runtime;

public void Main()
{
    try
    {
        string folderPath      = Dts.Variables[&quot;$Package::SourceFolderPath&quot;].Value.ToString();
        string cleanedPrefix   = Dts.Variables[&quot;$Package::CleanedFilePrefix&quot;].Value.ToString();
        string origPrefix      = Dts.Variables[&quot;$Package::OrigFilePrefix&quot;].Value.ToString();
        string dateOverride    = Dts.Variables[&quot;$Package::FileDateOverride&quot;].Value.ToString();
        bool   isBackfill      = (bool)Dts.Variables[&quot;$Package::IsManualBackfill&quot;].Value;
        bool   isFileNameDateConstrained = (bool)Dts.Variables[&quot;User::IsFileNameDateConstrained&quot;].Value;
        DateTime nextExpected  = (DateTime)Dts.Variables[&quot;User::NextExpectedDateValue&quot;].Value;

        DateTime targetDate;

        if (isBackfill &amp;&amp; !string.IsNullOrWhiteSpace(dateOverride))
        {
            if (!DateTime.TryParseExact(dateOverride, &quot;yyyyMMdd&quot;,
                    System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.None, out targetDate))
            {
                Dts.Events.FireError(0, &quot;Discover File + Extract FileDate&quot;,
                    &quot;FileDateOverride '&quot; + dateOverride + &quot;' is not a valid yyyyMMdd date.&quot;, &quot;&quot;, 0);
                Dts.TaskResult = (int)ScriptResults.Failure;
                return;
            }
        }
        else if (isFileNameDateConstrained)
        {
            // The core fix: expected date comes from the control table,
            // not from DateTime.Today / GETDATE().
            targetDate = nextExpected;
        }
        else
        {
            // Neither backfill nor filename-date-constrained. No file-date
            // concept applies to this job (e.g. CalendarDayRun-style job) -
            // default to today, same treatment as CalendarDayRun jobs.
            // This is a judgment call made in the absence of a concrete
            // example - revisit if this job ever actually hits this branch.
            targetDate = DateTime.Today;

            Dts.Events.FireInformation(0, &quot;Discover File + Extract FileDate&quot;,
                &quot;IsFileNameDateConstrained is False and this is not a backfill run. &quot; +
                &quot;Defaulting FileDate to today (&quot; + targetDate.ToString(&quot;yyyy-MM-dd&quot;) + &quot;).&quot;,
                &quot;&quot;, 0, ref boolPassThrough);
        }

        string dateSuffix = targetDate.ToString(&quot;yyyyMMdd&quot;);

        string cleanedFileName = cleanedPrefix + dateSuffix + &quot;.txt&quot;;
        string origFileName    = origPrefix + dateSuffix + &quot;.txt&quot;;

        string cleanedFullPath = Path.Combine(folderPath, cleanedFileName);
        string origFullPath    = Path.Combine(folderPath, origFileName);

        if (!File.Exists(cleanedFullPath))
        {
            Dts.Events.FireError(0, &quot;Discover File + Extract FileDate&quot;,
                &quot;Expected cleaned file not found: &quot; + cleanedFullPath +
                &quot;. NextExpectedDateValue was not advanced by the prior run - &quot; +
                &quot;next attempt will look for this same date again.&quot;, &quot;&quot;, 0);
            Dts.TaskResult = (int)ScriptResults.Failure;
            return;
        }

        // File stability check - avoid reading a half-written file.
        long sizeFirst = new FileInfo(cleanedFullPath).Length;
        System.Threading.Thread.Sleep(5000);
        long sizeSecond = new FileInfo(cleanedFullPath).Length;

        if (sizeFirst != sizeSecond)
        {
            Dts.Events.FireError(0, &quot;Discover File + Extract FileDate&quot;,
                &quot;Cleaned file size changed between checks - may still be writing. Aborting this run.&quot;, &quot;&quot;, 0);
            Dts.TaskResult = (int)ScriptResults.Failure;
            return;
        }

        Dts.Variables[&quot;User::FileDate&quot;].Value            = targetDate;
        Dts.Variables[&quot;User::CleanedFileName&quot;].Value      = cleanedFileName;
        Dts.Variables[&quot;User::CleanedFileFullPath&quot;].Value  = cleanedFullPath;
        Dts.Variables[&quot;User::OrigFileName&quot;].Value         = origFileName;
        Dts.Variables[&quot;User::OrigFileFullPath&quot;].Value     = origFullPath;

        Dts.TaskResult = (int)ScriptResults.Success;
    }
    catch (Exception ex)
    {
        Dts.Events.FireError(0, &quot;Discover File + Extract FileDate&quot;,
            &quot;Unhandled exception: &quot; + ex.Message, &quot;&quot;, 0);
        Dts.TaskResult = (int)ScriptResults.Failure;
    }
}

private bool boolPassThrough = false;
</code></pre>

Q: Obtain Bearer token, using only Client ID and Secret. Is it possible A: <p>Yes, it's Possible.</p>
<p>Reference : <br></p>
<ol>
<li><p><a href="https://stackoverflow.com/questions/52238839/access-keycloak-rest-admin-api-using-a-service-account-client-credential-grant">Access Keycloak REST Admin API using a service account (client credential grant)</a></p>
</li>
<li><p><a href="https://www.keycloak.org/docs/latest/server_admin/index.html#_service_accounts" rel="nofollow noreferrer">https://www.keycloak.org/docs/latest/server_admin/index.html#_service_accounts</a></p>
</li>
</ol>
<p>Steps to do in Keycloak : <br>
Step 1: Click Clients in the menu<br></p>
<ul>
<li>Click the Settings tab<br></li>
<li>Select your client<br></li>
<li>Enable Service  Account to On.<br></li>
</ul>
<p>Step 2 : Click the Scope tab, <br></p>
<ul>
<li>Verify that you have roles or toggle <code>Full Scope Allowed</code> to ON.<br>
<br></li>
</ul>
<p>Code:<br></p>
<pre><code>    public AuthenticationResponse getAccessTokenByClientIdAndClientSecret(AuthorizationRequest authorizationRequest) {
    try {
        log.trace(&quot;Generating authentication token using client credentials&quot;);
        RestTemplate restTemplate = restTemplateBuilder.build();
        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_FORM_URLENCODED);

        MultiValueMap&lt;String, String&gt; body = new LinkedMultiValueMap&lt;&gt;();
        body.add(GRANT_TYPE, CLIENT_CREDENTIALS);
        body.add(CLIENT_ID, authorizationRequest.getClientId());
        body.add(CLIENT_SECRET, authorizationRequest.getClientSecret());

        HttpEntity&lt;MultiValueMap&lt;String, String&gt;&gt; request = new HttpEntity&lt;&gt;(body, headers);

        ResponseEntity&lt;String&gt; response = restTemplate.postForEntity(keycloakUrl + REALMS + keycloakRealm + PROTOCOL_OPENID_CONNECT_TOKEN,
                request, String.class);

        ObjectMapper mapper = new ObjectMapper().disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
        AuthenticationResponse authenticationResponse = mapper.readValue(response.getBody(), AuthenticationResponse.class);
        log.trace(&quot;Token generated successfully, now returning to calling function&quot;);
        return authenticationResponse;
    } catch (Exception ex) {
        log.error(&quot;Exception occurred while generating access token: {}&quot;, ex.getMessage());
        throw ex;
    }
}
</code></pre>

Q: how to add custom md-chips in addition to existing md-chips? A: <p>You need to write a function to set 'skill_title'</p>

<p><strong>VIEW</strong></p>

<pre><code>&lt;div ng-controller="BasicDemoCtrl as ctrl" layout="column" ng-cloak="" ng-app="MyApp"&gt;
  &lt;md-content class="md-padding" layout="column"&gt;
    &lt;md-chips ng-model="ctrl.skills" readonly="ctrl.readonly" md-transform-chip="ctrl.newSkill($chip)"&gt;
      &lt;md-chip-template&gt;
        &lt;span&gt;
          &lt;strong&gt;{{$chip.skill_title}}&lt;/strong&gt;
        &lt;/span&gt;
      &lt;/md-chip-template&gt;
    &lt;/md-chips&gt;
  &lt;/md-content&gt;
&lt;/div&gt;
</code></pre>

<p><strong>Controller</strong></p>

<pre><code>(function () {
      'use strict';
      angular
          .module('MyApp')
          .controller('BasicDemoCtrl', DemoCtrl);
      function DemoCtrl ($timeout, $q) {
        var self = this;

    self.skills = [
      {
        'skill_title' : 'Angular'
      },
      {
        'skill_title' : 'Material'
      },
      {
        'skill_title' : 'C#'
      }
    ];

    self.newSkill = function(chip) {
      return {
        skill_title: chip
      };
    };
  }
})();
</code></pre>

